CREATE TABLE `workflow_handoffs` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`window_id` integer NOT NULL,`measurement_version_id` integer NOT NULL,`design_version_id` integer NOT NULL,`qa_run_id` integer NOT NULL,`revision` integer NOT NULL,`source_hash` text NOT NULL,`source_snapshot_json` text NOT NULL,`idempotency_key` text NOT NULL,`status` text DEFAULT 'prepared' NOT NULL,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `workflow_handoffs_idempotency_key_unique` ON `workflow_handoffs` (`idempotency_key`); CREATE UNIQUE INDEX `workflow_handoffs_window_revision_unique` ON `workflow_handoffs` (`window_id`,`revision`); CREATE INDEX `workflow_handoffs_window_idx` ON `workflow_handoffs` (`window_id`);
CREATE TABLE `workflow_artifacts` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`handoff_id` integer NOT NULL,`artifact_type` text NOT NULL,`status` text NOT NULL,`external_record_id` text,`snapshot_json` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `workflow_artifacts_handoff_type_unique` ON `workflow_artifacts` (`handoff_id`,`artifact_type`);
